{"command": "cat > /workspace/update_pat5b.py << 'EOF'
import json
CH = {"KICK":0, "SNARE":1, "HAT":2, "BASS":3, "LEAD":4, "ARP":5, "PAD":6, "PLUCK":7}
ROWS = 64
BATCH = []

def cell(pat, row, ch, note=None, inst=None, vol=None):
    args = {"pattern":pat, "row":row, "channel":ch}
    if note: args["note"] = note
    if inst: args["instrument"] = inst
    if vol: args["volume"] = vol
    BATCH.append({"name":"pattern_set_cell","arguments":args})

# Build drums like intro
cell(5,0,CH["KICK"],"C-2",1,64)
for r in [8,16,24,32,40,48,56]:
    cell(5,r,CH["KICK"],"C-2",1,52)
for r in [24,56]:
    cell(5,r,CH["SNARE"],"C-2",2,48)
for r in range(0,64,4):
    cell(5,r,CH["HAT"],"C-2",3,24)

bass_lines = {
    "Em": ["E-1", "E-1", "G-1", "E-1"]*4,
    "C":  ["C-1", "C-1", "E-1", "C-1"]*4,
    "G":  ["G-0", "G-0", "B-0", "G-0"]*4,
}
arp_notes = {
    "Em": ["E-3","G-3","B-3","E-4"]*4,
    "C":  ["C-3","E-3","G-3","C-4"]*4,
    "G":  ["G-2","B-2","D-3","G-3"]*4,
}
chords = {"Em": ["E-2"], "C": ["C-2"], "G": ["G-1"]}

for bar,ch in enumerate(["Em","C","G","Em"]):
    sr = bar*16
    line = bass_lines.get(ch, bass_lines["Em"])
    arp = arp_notes.get(ch, arp_notes["Em"])
    root = chords.get(ch, ["E-2"])[0]
    for i,n in enumerate(line):
        if sr+i < ROWS:
            cell(5, sr+i, CH["BASS"], n, 6, 44 if i%4==0 else 36)
    for i,n in enumerate(arp):
        if sr+i < ROWS:
            cell(5, sr+i, CH["ARP"], n, 5, 30 if i%4==0 else 24)
    cell(5, sr, CH["PAD"], root, 7, 28)
    if bar == 3:
        cell(5, sr+8, CH["PLUCK"], root, 8, 36)

with open('/workspace/update_pat5b.json','w') as f:
    json.dump(BATCH, f)
print('wrote', len(BATCH))
EOF
python3 /workspace/update_pat5b.py && ft2 batch /workspace/update_pat5b.json"}

